public sealed class WorkerConfig
{
    public int MaxRetries { get; init; } = 3;
    public string QueueName { get; init; } = "default";

    public string DisplayName =>
        $"{QueueName} (retries={MaxRetries})";
}

public sealed class LegacyType
{
    public string field { get; set; } = "member";

    public string Value
    {
        get => @field; // refers to the member above
        set => field = value; // refers to backing field (C# 14)
    }
}
